 "content": "def transform(grid):
    # Extract all unusual colors positioned on near-uniform lattice separator rows.
    from collections import Counter
    counts=Counter(v for row in grid for v in row)
    rare={v for v,n in counts.items() if n <= 8}
    rows=[]
    for row in grid:
        vals=[v for v in row if v in rare]
        if vals: rows.append(vals)
    return rows
